package com.yeyamo_mobile.api.feed_service.application;import org.springframework.boot.context.properties.ConfigurationProperties;import org.springframework.stereotype.Component;import java.util.*;
@Component@ConfigurationProperties(prefix="yeyamo.feed.mix")public class FeedMixProperties{private Map<String,Double>weights=new HashMap<>(Map.of("SOCIAL",1d,"PLACE",1d,"EVENT",1d,"CULTURE_CONTENT",1d,"LANGUAGE_LESSON",1d,"ARTWORK",1d,"CULTURE_CHALLENGE",1d,"ARTISAN",1d));public Map<String,Double>getWeights(){return weights;}public void setWeights(Map<String,Double>w){weights=w;}public double weight(String type){return Math.max(0,weights.getOrDefault(type,1d));}}
